@@ -28,18 +29,33 @@ public final class ZipUtils {
     private ZipUtils() {}

     public static void unzip(InputStream is, Path target) throws IOException {
+        Path normalizedTarget = target.toAbsolutePath().normalize();
         try (ZipInputStream zis = new ZipInputStream(is)) {
             ZipEntry entry;
             while ((entry = zis.getNextEntry()) != null) {
-                Path resolvedPath = target.resolve(entry.getName());
