 pub fn parse_qe_identity(collateral: &Collateral) -> Result<QeIdentity, QuoteVerificationError> {
+    verify_qe_identity_signature(collateral)?;
     serde_json::from_str::<QeIdentity>(&collateral.qe_identity)
         .map_err(|_| QuoteVerificationError::InvalidQeIdentity)
 }

+fn verify_qe_identity_signature(collateral: &Collateral) -> Result<(), QuoteVerificationError> {
+    verify_pcs_signed_json(
+        collateral.qe_identity.as_bytes(),
+        &collateral.qe_identity_signature,
+        &collateral.qe_identity_issuer_chain,
+    )
+    .map_err(|_| QuoteVerificationError::InvalidQeIdentitySignature)
+}
+
+pub fn enforce_qe_report_policy(
+    qe_report: &EnclaveReportBody,
+    qe_identity: &QeIdentity,
+) -> Result<(), QuoteVerificationError> {
+    let id = &qe_identity.enclave_identity;
+
+    let miscselect = u32::from_str_radix(id.miscselect.trim_start_matches("0x"), 16)
+        .map_err(|_| QuoteVerificationError::InvalidQeIdentity)?;
+    let miscselect_mask = u32::from_str_radix(id.miscselect_mask.trim_start_matches("0x"), 16)
+        .map_err(|_| QuoteVerificationError::InvalidQeIdentity)?;
+    if (qe_report.misc_select & miscselect_mask) != (miscselect & miscselect_mask) {
+        return Err(QuoteVerificationError::InvalidQeReportIdentity);
+    }
+
+    let expected_attrs = hex_decode(id.attributes.trim_start_matches("0x"))
+        .map_err(|_| QuoteVerificationError::InvalidQeIdentity)?;
+    let attr_mask = hex_decode(id.attributes_mask.trim_start_matches("0x"))
+        .map_err(|_| QuoteVerificationError::InvalidQeIdentity)?;
+    let report_attrs = qe_report.attributes.to_vec();
+    if expected_attrs.len() != report_attrs.len() || attr_mask.len() != report_attrs.len() {
+        return Err(QuoteVerificationError::InvalidQeIdentity);
+    }
+    for i in 0..report_attrs.len() {
+        if (report_attrs[i] & attr_mask[i]) != (expected_attrs[i] & attr_mask[i]) {
+            return Err(QuoteVerificationError::InvalidQeReportIdentity);
+        }
+    }
+
+    let expected_mrsigner = hex_decode(id.mr_signer.trim_start_matches("0x"))
+        .map_err(|_| QuoteVerificationError::InvalidQeIdentity)?;
+    if qe_report.mr_signer.as_ref() != expected_mrsigner.as_slice() {
+        return Err(QuoteVerificationError::InvalidQeReportIdentity);
+    }
+
+    if qe_report.isv_prod_id != id.isv_prod_id {
+        return Err(QuoteVerificationError::InvalidQeReportIdentity);
+    }
+
+    Ok(())
+}
+
